import{_ as a,o as e,c as s,a2 as i}from"./chunks/framework.iXqqCa-C.js";const r="/images/misskey-lists.webp",n="/images/misskey-antennas.webp",u=JSON.parse('{"title":"列表与天线","description":"","frontmatter":{},"headers":[],"relativePath":"guide/misskey/lists-antennas.md","filePath":"guide/misskey/lists-antennas.md","lastUpdated":1793501934000}'),l={name:"guide/misskey/lists-antennas.md"};function d(o,t,h,p,c,_){return e(),s("div",null,[...t[0]||(t[0]=[i('<h1 id="列表与天线" tabindex="-1">列表与天线 <a class="header-anchor" href="#列表与天线" aria-label="Permalink to &quot;列表与天线&quot;">​</a></h1><p>列表和天线是两种定制信息流的工具：列表按<strong>人</strong>组织，天线按<strong>关键词</strong>组织。</p><h2 id="列表" tabindex="-1">列表 <a class="header-anchor" href="#列表" aria-label="Permalink to &quot;列表&quot;">​</a></h2><p>列表（Lists）是自建的用户分组，列表时间线只显示组内用户的帖子，可选择是否包含回复。</p><ul><li>通过侧栏「列表」创建，例如「好友」「画师」。</li><li>在<a href="/guide/posts#时间线">时间线</a>中切换到列表查看。</li><li>列表只有自己能看到。</li><li>列表上限和每个列表的成员数上限由服务器策略决定。</li></ul><p><img src="'+r+'" alt="列表管理"></p><h2 id="天线" tabindex="-1">天线 <a class="header-anchor" href="#天线" aria-label="Permalink to &quot;天线&quot;">​</a></h2><p>天线（Antennas）按条件自动收集帖子，例如追踪包含某个关键词的所有新帖。</p><ul><li>通过侧栏「天线」创建，每个天线有独立时间线。</li><li>天线数量上限由服务器策略决定。</li><li>可设置的条件：</li></ul><table tabindex="0"><thead><tr><th>条件</th><th>说明</th></tr></thead><tbody><tr><td>接收来源</td><td>所有帖子 / 已关注用户的帖子 / 来自指定用户 / 来自指定列表 / 过滤指定用户后的所有帖子</td></tr><tr><td>包含关键字</td><td>空格分隔为 AND，换行分隔为 OR</td></tr><tr><td>排除关键字</td><td>规则同上，命中则不收录</td></tr><tr><td>其他</td><td>区分大小写、排除机器人账户、包含回复、仅带有附件的帖子、排除敏感频道的帖子</td></tr></tbody></table><p><img src="'+n+'" alt="天线管理"></p><h2 id="如何选择" tabindex="-1">如何选择 <a class="header-anchor" href="#如何选择" aria-label="Permalink to &quot;如何选择&quot;">​</a></h2><p>想看<strong>某些人</strong>的动态用列表，想追踪<strong>某类内容</strong>（不论作者）用天线。</p>',13)])])}const g=a(l,[["render",d]]);export{u as __pageData,g as default};
